// --- KONRAD3D observed-history track stabilisation ---------------------------
// Official KONRAD3D forecast centroids remain authoritative. If a current cell
// only has the motion-vector projection generated by MID, use consecutive DWD
// KONRAD3D observations to derive a short, quality-gated trajectory instead.
// This improves continuity without inventing radar motion or timestamps.
const MID_KONRAD_HISTORY_LOOKBACK_MS=30*60_000;
const MID_KONRAD_HISTORY_MAX_FRAMES=4;
const MID_KONRAD_HISTORY_LEADS=[15,30,45,60];
const midKonradBaseNowcast=dwdKonrad3dNowcast;

function midKonradHistoryFiles(indexHtml,observedMs){
 const names=[...String(indexHtml||'').matchAll(/KONRAD3D_\d{8}T\d{6}\.xml/gi)].map(match=>match[0]),seen=new Set();
 return names.map(name=>({name,time:konradTimestamp(name)})).filter(item=>{
  if(seen.has(item.name)||!Number.isFinite(item.time)){return false}seen.add(item.name);
  return item.time<observedMs-30_000&&item.time>=observedMs-MID_KONRAD_HISTORY_LOOKBACK_MS;
 }).sort((a,b)=>b.time-a.time).slice(0,MID_KONRAD_HISTORY_MAX_FRAMES);
}
function midKonradCellId(cell){const value=String(cell?.id||'').trim().toLowerCase();return value&&!/^cell-\d+$/.test(value)?value:''}
function midKonradAngleDifference(a,b){const delta=Math.abs((((Number(a)-Number(b))+540)%360)-180);return Number.isFinite(delta)?delta:180}
function midKonradTrackPointTime(observedMs,point){
 const existing=Date.parse(String(point?.time||''));if(Number.isFinite(existing))return new Date(existing).toISOString();
 const minutes=number(point?.minutes);return Number.isFinite(observedMs)&&Number.isFinite(minutes)?new Date(observedMs+minutes*60_000).toISOString():undefined;
}
function midKonradStampTrackTimes(cell,observedMs){
 if(!Array.isArray(cell?.trackForecasts))return cell;
 return{...cell,trackForecasts:cell.trackForecasts.map(point=>({...point,time:midKonradTrackPointTime(observedMs,point)}))};
}
async function midKonradHistoryRuns(lat,lon,observedMs){
 for(const root of DWD_KONRAD3D_ROOTS){try{
  const index=await fetchText(root,{'Accept':'text/html,application/xhtml+xml'}),files=midKonradHistoryFiles(index,observedMs);if(files.length<2)continue;
  const settled=await Promise.allSettled(files.map(async file=>{const observedAt=new Date(file.time).toISOString(),xml=await fetchText(new URL(file.name,root).toString(),{'Accept':'application/xml,text/xml,*/*'});return{time:file.time,observedAt,cells:parseKonradCells(xml,lat,lon,observedAt)}}));
  const runs=settled.filter(result=>result.status==='fulfilled'&&Array.isArray(result.value?.cells)).map(result=>result.value).sort((a,b)=>b.time-a.time);if(runs.length>=2)return runs;
 }catch{}
 }
 return[];
}
function midKonradHistoricalCandidate(run,anchor,currentCell){
 const stableId=midKonradCellId(currentCell);let candidate=stableId?run.cells.find(cell=>midKonradCellId(cell)===stableId):undefined;
 if(candidate)return{cell:candidate,exact:true};
 let nearest,distanceKm=Infinity;for(const cell of run.cells){const current=distance(anchor.latitude,anchor.longitude,cell.latitude,cell.longitude)/1000;if(current<distanceKm){nearest=cell;distanceKm=current}}
 const dtMinutes=Math.max(1,(anchor.time-run.time)/60_000),declaredSpeed=Math.max(0,number(currentCell?.speedKmh)||0),plausibleKm=Math.min(22,Math.max(8,(declaredSpeed||90)*dtMinutes/60*1.8+3));
 return nearest&&distanceKm<=plausibleKm?{cell:nearest,exact:false}:null;
}
function midKonradObservedMotion(cell,runs,observedMs){
 const currentLat=number(cell?.latitude),currentLon=number(cell?.longitude);if(currentLat===undefined||currentLon===undefined)return null;
 const positions=[{time:observedMs,latitude:currentLat,longitude:currentLon,exact:true}],ordered=[...runs].sort((a,b)=>b.time-a.time);let anchor=positions[0],exactMatches=0;
 for(const run of ordered){const match=midKonradHistoricalCandidate(run,anchor,cell);if(!match)continue;const point={time:run.time,latitude:number(match.cell.latitude),longitude:number(match.cell.longitude),exact:match.exact};if(point.latitude===undefined||point.longitude===undefined)continue;const dtHours=(anchor.time-point.time)/3_600_000,travelKm=distance(point.latitude,point.longitude,anchor.latitude,anchor.longitude)/1000,speed=dtHours>0?travelKm/dtHours:Infinity;if(!Number.isFinite(speed)||speed>180)continue;positions.unshift(point);anchor=point;if(match.exact)exactMatches++}
 if(positions.length<3)return null;
 const spanMinutes=(positions.at(-1).time-positions[0].time)/60_000;if(spanMinutes<8||spanMinutes>32)return null;
 const segments=[];for(let index=1;index<positions.length;index++){const from=positions[index-1],to=positions[index],hours=(to.time-from.time)/3_600_000;if(hours<=0)continue;const travelKm=distance(from.latitude,from.longitude,to.latitude,to.longitude)/1000,speedKmh=travelKm/hours,direction=bearingTowards(from.latitude,from.longitude,to.latitude,to.longitude);if(!Number.isFinite(speedKmh)||speedKmh>180)continue;segments.push({speedKmh,direction,travelKm})}
 if(segments.length<2||segments.reduce((sum,row)=>sum+row.travelKm,0)<1)return null;
 let east=0,north=0,weightSum=0;segments.forEach((segment,index)=>{const weight=.65+.35*(index+1)/segments.length,radians=segment.direction*Math.PI/180;east+=Math.sin(radians)*segment.speedKmh*weight;north+=Math.cos(radians)*segment.speedKmh*weight;weightSum+=weight});east/=weightSum;north/=weightSum;const speedKmh=Math.hypot(east,north),direction=(Math.atan2(east,north)*180/Math.PI+360)%360;if(speedKmh<3||speedKmh>180)return null;
 const directionSpread=Math.max(...segments.map(segment=>midKonradAngleDifference(segment.direction,direction))),meanSpeed=segments.reduce((sum,row)=>sum+row.speedKmh,0)/segments.length,speedVariance=segments.reduce((sum,row)=>sum+(row.speedKmh-meanSpeed)**2,0)/segments.length,speedStd=Math.sqrt(speedVariance);if(directionSpread>60||speedStd>Math.max(35,meanSpeed*.75))return null;
 const productDirection=number(cell?.motionDirectionDeg),productSpeed=number(cell?.speedKmh);if(productDirection!==undefined&&productSpeed!==undefined&&productSpeed>=8){if(midKonradAngleDifference(productDirection,direction)>80)return null;const ratio=speedKmh/productSpeed;if(ratio<.28||ratio>3.2)return null}
 return{positions,exactMatches,speedKmh,direction,directionSpread,speedStd,confidence:exactMatches>=2&&directionSpread<=35&&speedStd<=Math.max(18,meanSpeed*.45)?'high':'medium'};
}
function midKonradHistoryProjection(cell,motion,observedMs,siteLat,siteLon){
 const originLat=number(cell?.latitude),originLon=number(cell?.longitude);if(originLat===undefined||originLon===undefined)return[];const footprintRadius=Math.max(2.5,Math.min(8,(number(cell?.currentImpactRadiusKm)||6)*.45));
 return MID_KONRAD_HISTORY_LEADS.map(minutes=>{const travelKm=motion.speedKmh*minutes/60,projected=destinationPoint(originLat,originLon,motion.direction,travelKm),directionTerm=travelKm*Math.sin(Math.min(60,motion.directionSpread)*Math.PI/180)*.55,speedTerm=motion.speedStd*minutes/60*.65,major=Math.min(24,Math.max(3,footprintRadius+minutes*.055+directionTerm+speedTerm)),minor=Math.min(major,Math.max(2.5,major*.64)),distanceKm=distance(siteLat,siteLon,projected.latitude,projected.longitude)/1000;return{...projected,minutes,time:new Date(observedMs+minutes*60_000).toISOString(),distanceKm,effectiveDistanceKm:Math.max(0,distanceKm-major),uncertaintyKm:Number(major.toFixed(2)),uncertaintyMinorKm:Number(minor.toFixed(2)),uncertaintyOrientationDeg:Number(motion.direction.toFixed(1)),derived:true,trackBasis:'observed-history'}});
}
function midKonradEnhanceCell(cell,runs,observedMs,siteLat,siteLon){
 const stamped=midKonradStampTrackTimes(cell,observedMs),track=Array.isArray(stamped?.trackForecasts)?stamped.trackForecasts:[],official=track.filter(point=>point?.derived!==true&&number(point?.latitude)!==undefined&&number(point?.longitude)!==undefined);if(official.length)return stamped;
 const motion=midKonradObservedMotion(stamped,runs,observedMs);if(!motion)return stamped;
 const projected=midKonradHistoryProjection(stamped,motion,observedMs,siteLat,siteLon);if(!projected.length)return stamped;
 const nearestForecast=projected.reduce((best,row)=>!best||row.effectiveDistanceKm<best.effectiveDistanceKm?row:best,undefined),last=projected.at(-1);return{...stamped,trackForecasts:projected,trackSource:'DWD KONRAD3D · beobachtete Zellhistorie',trackConfidence:motion.confidence,trackObservedPositions:motion.positions.length,trackHistoryStartAt:new Date(motion.positions[0].time).toISOString(),trackHistoryEndAt:new Date(observedMs).toISOString(),observedTrackSpeedKmh:Number(motion.speedKmh.toFixed(1)),observedTrackDirectionDeg:Number(motion.direction.toFixed(1)),forecastDistanceKm:nearestForecast?.distanceKm,forecastEffectiveDistanceKm:nearestForecast?.effectiveDistanceKm,forecastUncertaintyKm:nearestForecast?.uncertaintyKm,forecastTime:nearestForecast?.time,forecastLatitude:nearestForecast?.latitude,forecastLongitude:nearestForecast?.longitude,trackForecastTime:last?.time,trackForecastLatitude:last?.latitude,trackForecastLongitude:last?.longitude,trackForecastUncertaintyKm:last?.uncertaintyKm};
}

dwdKonrad3dNowcast=async function midKonrad3dNowcastWithObservedHistory(lat,lon,country=''){
 const base=await midKonradBaseNowcast(lat,lon,country),observedMs=Date.parse(String(base?.observedAt||'')),cells=Array.isArray(base?.nearbyCells)?base.nearbyCells:[];if(!base?.available||!Number.isFinite(observedMs)||!cells.length)return base;
 const stampedCells=cells.map(cell=>midKonradStampTrackTimes(cell,observedMs)),needsHistory=stampedCells.some(cell=>!(cell.trackForecasts||[]).some(point=>point?.derived!==true&&number(point?.latitude)!==undefined&&number(point?.longitude)!==undefined));if(!needsHistory){const nearest=base?.nearest?midKonradStampTrackTimes(base.nearest,observedMs):stampedCells[0];return{...base,nearbyCells:stampedCells,nearest}}
 const runs=await midKonradHistoryRuns(lat,lon,observedMs),enhancedCells=stampedCells.map(cell=>midKonradEnhanceCell(cell,runs,observedMs,lat,lon));let nearest=enhancedCells[0];
 if(base?.nearest){const nearestId=String(base.nearest.id||''),matched=enhancedCells.find(cell=>String(cell.id||'')===nearestId);nearest=matched||midKonradEnhanceCell(base.nearest,runs,observedMs,lat,lon)}
 if(nearest?.trackSource?.includes('beobachtete Zellhistorie')){try{const historyTrack=nearest.trackForecasts,enriched=await enrichStormAffectedPlaces(nearest,lat,lon,base.observedAt);nearest={...enriched,trackForecasts:historyTrack,trackSource:nearest.trackSource,trackConfidence:nearest.trackConfidence,trackObservedPositions:nearest.trackObservedPositions,trackHistoryStartAt:nearest.trackHistoryStartAt,trackHistoryEndAt:nearest.trackHistoryEndAt,observedTrackSpeedKmh:nearest.observedTrackSpeedKmh,observedTrackDirectionDeg:nearest.observedTrackDirectionDeg};enhancedCells[0]=nearest}catch{}}
 const historyCount=enhancedCells.filter(cell=>cell?.trackSource?.includes('beobachtete Zellhistorie')).length;return{...base,nearbyCells:enhancedCells,nearest,diagnostics:{...(base.diagnostics||{}),trackHistoryFrames:runs.length,historyTrackedCells:historyCount,trackTiming:'actual-konrad-run-plus-lead'}};
};
